-- Footloose Alley Studio Manager v5.5.0 studio expenses and reconciliation.
begin;
create table if not exists public."Studio_Expenses"(id bigint generated by default as identity primary key,expense_date date not null default current_date,category text not null,description text not null,amount numeric(10,2) not null,payment_method text not null,reference_number text,notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint studio_expenses_amount_check check(amount>0),constraint studio_expenses_category_check check(length(trim(category)) between 2 and 60),constraint studio_expenses_description_check check(length(trim(description)) between 2 and 200));
create index if not exists studio_expenses_date_idx on public."Studio_Expenses"(expense_date desc);
create table if not exists public."Cash_Reconciliations"(id bigint generated by default as identity primary key,reconciliation_date date not null unique,opening_cash numeric(10,2) not null default 0,cash_income numeric(10,2) not null default 0,cash_expenses numeric(10,2) not null default 0,expected_cash numeric(10,2) not null,counted_cash numeric(10,2) not null,variance numeric(10,2) not null,notes text,reconciled_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['Studio_Expenses','Cash_Reconciliations'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists finance_select on public.%I',t);execute format('create policy finance_select on public.%I for select to authenticated using(public.current_app_role() in(''admin'',''receptionist''))',t);execute format('drop policy if exists finance_insert on public.%I',t);execute format('create policy finance_insert on public.%I for insert to authenticated with check(public.current_app_role() in(''admin'',''receptionist''))',t);execute format('drop policy if exists finance_update on public.%I',t);execute format('create policy finance_update on public.%I for update to authenticated using(public.current_app_role() in(''admin'',''receptionist'')) with check(public.current_app_role() in(''admin'',''receptionist''))',t);execute format('grant select,insert,update on public.%I to authenticated',t);end loop;end $$;
commit;
